import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

tall_skinny_matmul_kernel = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void tall_skinny_matmul_kernel(const float* A, const float* B_T, float* C, int M, int N) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    int j = blockIdx.y * blockDim.y + threadIdx.y;

    if (i >= M || j >= M) return;

    float sum = 0.0f;
    for (int k = 0; k < N; ++k) {
        sum += A[i * N + k] * B_T[j * N + k];
    }
    C[i * M + j] = sum;
}

torch::Tensor tall_skinny_matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int M = A.size(0);
    int N = A.size(1);

    auto B_T = B.transpose(0, 1).contiguous();
    auto C = torch::zeros({M, M}, A.options());

    dim3 threads(32, 32);
    dim3 blocks((M + threads.x - 1) / threads.x, (M + threads.y - 1) / threads.y);

    tall_skinny_matmul_kernel<<<blocks, threads>>>(
        A.data_ptr<float>(),
        B_T.data_ptr<float>(),
        C.data_ptr<float>(),
        M,
        N
    );

    return C;
}
"""

tall_skinny_matmul_cpp = "torch::Tensor tall_skinny_matmul_cuda(torch::Tensor A, torch::Tensor B);"

tall_skinny_matmul = load_inline(
    name='tall_skinny_matmul',
    cpp_sources=tall_skinny_matmul_cpp,
    cuda_sources=tall_skinny_matmul_kernel,
    functions=['tall_skinny_matmul_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A, B):
        return tall_skinny_matmul.tall_skinny_matmul_cuda(A, B)
